// SPDX-License-Identifier: ISC
//! Owner-only creation of the files and directories that hold node
//! secrets.
//!
//! dcrd applies restrictive modes at creation time: the home directory
//! and the config directory are made with `os.MkdirAll(dir, 0700)`
//! (`config.go` 471 and 770), the autogenerated `dcrd.conf` — which
//! carries a freshly generated `rpcuser`/`rpcpass` pair — with
//! `os.OpenFile(destPath, O_RDWR|O_CREATE|O_TRUNC, 0600)`
//! (`config.go` 506), and the autogenerated RPC key with
//! `os.WriteFile(keyFile, key, 0600)` (`server.go` 3592).  Go passes
//! the mode to `open(2)`/`mkdir(2)` itself, so the secret is never
//! reachable by other local users, not even for the instant between
//! the write and a follow-up `chmod`.
//!
//! `std::fs::write` and `std::fs::create_dir_all` take no mode, so they
//! would create with `0666`/`0777` masked by the umask — world-readable
//! under the common `022`.  These helpers open with the mode instead.

use std::path::Path;

/// Create `path` readable and writable only by its owner and fill it
/// with `contents`, truncating any existing file.
///
/// The mode is supplied to `open(2)`, so a newly created file is never
/// momentarily readable by other users the way a write followed by a
/// `chmod` would be: a local user polling the path cannot open it while
/// it is still `0644` and keep the descriptor across the tightening.
///
/// `open(2)` only applies its mode when it creates the file, so a file
/// that already exists is handled separately, and this is where the
/// behaviour differs from dcrd's `os.WriteFile`:
///
/// * A pre-existing file whose group and other bits are all clear
///   (`0600`, `0700`, `0400`, …) is left completely alone — no `chmod`
///   is attempted.  A `0600` key provisioned by root, or one living on
///   an NFS/FUSE mount that rejects `fchmod`, therefore behaves exactly
///   as it does under dcrd: the file is opened, truncated, rewritten,
///   and startup proceeds.
/// * A pre-existing file that *is* reachable by other users is
///   restricted to `0600` **before** it is opened for truncation, so
///   the fresh secret never lands in a file another user already has
///   open or can still open.  dcrd instead rewrites the file through
///   its existing loose mode.
/// * If that restriction fails (`EPERM` because the file belongs to
///   another user, `EOPNOTSUPP` on an exotic mount) the error is
///   returned with nothing written and nothing truncated: the old file
///   survives byte for byte.  dcrd would start here, having written the
///   new secret into a file every local user can read; this refuses to
///   start instead, which is the one deliberate divergence in this
///   function.  It is fail-closed and non-destructive — the operator
///   fixes the mode or the ownership and starts again with the previous
///   secret still in place.
///
/// Like `os.WriteFile`, no `fsync` is performed.
#[cfg(unix)]
pub fn write_owner_only(path: &Path, contents: &[u8]) -> std::io::Result<()> {
    write_owner_only_hooked(
        path,
        contents,
        &mut |target: &Path| {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(target, std::fs::Permissions::from_mode(0o600))
        },
        &mut |_: &Path| {},
    )
}

/// Create `path` and fill it with `contents`.  Off Unix there is no
/// mode to apply, so this is plain `std::fs::write` — the same thing
/// dcrd's `os.WriteFile` reduces to on those platforms.
#[cfg(not(unix))]
pub fn write_owner_only(path: &Path, contents: &[u8]) -> std::io::Result<()> {
    std::fs::write(path, contents)
}

/// The body of [`write_owner_only`] with the two steps that cannot be
/// provoked from an unprivileged test — the `chmod` of a file this
/// process does not own, and the state of the file between its creation
/// and the write of the secret — exposed as seams.
///
/// `tighten` restricts an existing path to `0600`; the caller passes
/// `std::fs::set_permissions`, and the tests pass a failing stub to
/// check that a failure there destroys nothing.  `observed` is called
/// once the file exists with its final mode and has been truncated, but
/// before any secret byte has been written: that is the only instant at
/// which another user's `open(2)` could still race the contents, so it
/// is where the tests read the mode from.
#[cfg(unix)]
fn write_owner_only_hooked(
    path: &Path,
    contents: &[u8],
    tighten: &mut dyn FnMut(&Path) -> std::io::Result<()>,
    observed: &mut dyn FnMut(&Path),
) -> std::io::Result<()> {
    use std::fs::OpenOptions;
    use std::io::Write;
    use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};

    // Settle the mode of a file that already exists before anything
    // truncates it.  Nothing above this point may modify the target,
    // so an error return here leaves the previous secret intact.
    if let Ok(meta) = std::fs::metadata(path) {
        let mode = meta.permissions().mode() & 0o777;
        if meta.is_file() && mode & 0o077 != 0 {
            tighten(path).map_err(|e| {
                std::io::Error::new(
                    e.kind(),
                    format!(
                        "{} already exists with mode {mode:04o} and cannot be restricted to \
                         0600 ({e}); refusing to write a secret other local users could read",
                        path.display()
                    ),
                )
            })?;
        }
    }

    let mut file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(0o600)
        .open(path)?;
    observed(path);
    file.write_all(contents)?;
    file.flush()
}

/// Create `path` with an explicit mode and fill it with `contents`,
/// truncating any existing file.
///
/// For the files that are meant to be readable — the RPC certificate is
/// the only one — where dcrd still names a mode rather than letting the
/// umask decide.  `std::fs::write` asks for 0666, so under a permissive
/// umask it produces a group- and world-WRITABLE file where dcrd's
/// `os.WriteFile(certFile, cert, 0644)` does not.  For the certificate
/// that is an integrity question rather than a confidentiality one:
/// anyone who can write it can swap the identity the node serves.
///
/// Like `open(2)`, the mode applies only when the file is created, and it
/// is still masked by the umask; this narrows the request to dcrd's,
/// it does not widen anything.  A pre-existing file keeps its own mode —
/// see [`write_owner_only`] for the secret-bearing case, which does not
/// leave that to chance.
#[cfg(unix)]
pub fn write_with_mode(path: &Path, contents: &[u8], mode: u32) -> std::io::Result<()> {
    use std::fs::OpenOptions;
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;

    let mut file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(mode)
        .open(path)?;
    file.write_all(contents)?;
    file.flush()
}

/// Create `path` and fill it with `contents`.  Off Unix there is no mode
/// to apply, so this is plain `std::fs::write` — what `os.WriteFile`
/// reduces to on those platforms.
#[cfg(not(unix))]
pub fn write_with_mode(path: &Path, contents: &[u8], _mode: u32) -> std::io::Result<()> {
    std::fs::write(path, contents)
}

/// Create `path` and any missing parents, with every directory this
/// call creates reachable only by its owner (dcrd's
/// `os.MkdirAll(dir, 0700)`).
///
/// Directories that already exist keep their current mode, matching Go:
/// an operator who deliberately widened the data directory is not
/// overridden.
#[cfg(unix)]
pub fn create_dir_all_owner_only(path: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::DirBuilderExt;
    let mut builder = std::fs::DirBuilder::new();
    builder.recursive(true).mode(0o700);
    builder.create(path)
}

/// Create `path` and any missing parents.  Off Unix there is no mode to
/// apply, so this is plain `create_dir_all`.
#[cfg(not(unix))]
pub fn create_dir_all_owner_only(path: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(path)
}

#[cfg(all(test, unix))]
mod tests {
    use super::*;
    use std::os::unix::fs::PermissionsExt;

    fn mode_of(path: &Path) -> u32 {
        std::fs::metadata(path).unwrap().permissions().mode() & 0o777
    }

    /// What another local user racing the write would see: the mode the
    /// file carries and how much of the secret is already in it.
    fn snapshot(path: &Path) -> (u32, u64) {
        let meta = std::fs::metadata(path).unwrap();
        (meta.permissions().mode() & 0o777, meta.len())
    }

    /// The real tightening step, as production passes it.
    fn real_tighten(path: &Path) -> std::io::Result<()> {
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))
    }

    /// A tightening step that fails the way `fchmod` fails on a file
    /// owned by another user or on a mount that does not support it.
    fn failing_tighten(_path: &Path) -> std::io::Result<()> {
        Err(std::io::Error::from(std::io::ErrorKind::PermissionDenied))
    }

    #[test]
    fn a_fresh_secret_is_owner_only_before_its_contents_land() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("rpc.key");

        let mut at_creation = None;
        write_owner_only_hooked(&path, b"private key\n", &mut real_tighten, &mut |p| {
            at_creation = Some(snapshot(p));
        })
        .unwrap();

        let (mode, len) = at_creation.expect("the observation hook must run");
        assert_eq!(
            mode, 0o600,
            "the file must be owner-only from the moment open(2) creates it, not chmod'ed \
             after the secret is already in it"
        );
        assert_eq!(len, 0, "the observation point must precede the write");
        assert_eq!(std::fs::read(&path).unwrap(), b"private key\n");
        assert_eq!(mode_of(&path), 0o600);
    }

    #[test]
    fn a_world_readable_leftover_is_restricted_before_it_is_truncated() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("dcrd.conf");
        std::fs::write(&path, b"rpcpass=old\n").unwrap();
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o644)).unwrap();

        let mut at_creation = None;
        write_owner_only_hooked(&path, b"rpcpass=new\n", &mut real_tighten, &mut |p| {
            at_creation = Some(snapshot(p));
        })
        .unwrap();

        let (mode, len) = at_creation.expect("the observation hook must run");
        assert_eq!(
            mode, 0o600,
            "a leftover 0644 file must be restricted before the new secret is written, not \
             after: a chmod that follows the write cannot revoke a descriptor another user \
             already holds"
        );
        assert_eq!(len, 0, "the observation point must precede the write");
        assert_eq!(std::fs::read(&path).unwrap(), b"rpcpass=new\n");
        assert_eq!(mode_of(&path), 0o600);
    }

    #[test]
    fn a_secret_that_cannot_be_restricted_is_left_untouched() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("rpc.key");
        std::fs::write(&path, b"the previous key\n").unwrap();
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o644)).unwrap();

        let err =
            write_owner_only_hooked(&path, b"the new key\n", &mut failing_tighten, &mut |_| {
                panic!("the target must not be opened once the mode cannot be settled")
            })
            .expect_err("a failed restriction must be reported");

        assert_eq!(
            std::fs::read(&path).unwrap(),
            b"the previous key\n",
            "a failure while settling the mode must not have truncated the existing secret"
        );
        assert!(
            err.to_string().contains("0644"),
            "the error must name the offending mode: {err}"
        );
    }

    #[test]
    fn an_already_owner_only_secret_is_never_chmodded() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("rpc.key");
        std::fs::write(&path, b"the previous key\n").unwrap();
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).unwrap();

        // The file is writable but the chmod would fail — a key
        // provisioned by root in a group-writable directory, or one on
        // a mount that rejects fchmod.  dcrd's os.WriteFile starts fine
        // here because it never chmods an existing file, so this must
        // not even attempt it.
        let mut attempted = false;
        write_owner_only_hooked(
            &path,
            b"the new key\n",
            &mut |p| {
                attempted = true;
                failing_tighten(p)
            },
            &mut |_| {},
        )
        .expect("an owner-only file must be rewritten, not rejected");

        assert!(
            !attempted,
            "a file that is already unreachable by other users must not be chmod'ed: the \
             chmod can fail where dcrd succeeds, and failing here would refuse to start"
        );
        assert_eq!(std::fs::read(&path).unwrap(), b"the new key\n");
        assert_eq!(mode_of(&path), 0o600);
    }

    #[test]
    fn created_directories_are_owner_only() {
        let root = tempfile::tempdir().unwrap();
        let nested = root.path().join("a").join("b");

        create_dir_all_owner_only(&nested).unwrap();
        assert_eq!(mode_of(nested.parent().unwrap()), 0o700);
        assert_eq!(mode_of(&nested), 0o700);

        // Recreating an existing tree is a no-op and must not fail.
        create_dir_all_owner_only(&nested).unwrap();
    }
}
